```{shinylive-r}
#| standalone: true
#| viewerHeight: 700
#| components: [editor, viewer]

## file: app.R
library(shiny)

parameter_tabs <- tabsetPanel(
    id = "params",
    type = "hidden",
    tabPanel("normal",
             numericInput("mean", "mean", value = 1),
             numericInput("sd", "standard deviation", min = 0, value = 1)
    ),
    tabPanel("uniform",
             numericInput("min", "min", value = 0),
             numericInput("max", "max", value = 1)
    ),
    tabPanel("exponential",
             numericInput("rate", "rate", value = 1, min = 0),
    )
)

ui <- fluidPage(
    sidebarLayout(
        sidebarPanel(
            selectInput("dist", "Distribution",
                        choices = c("normal", "uniform", "exponential")
            ),
            numericInput("n", "Number of samples", value = 100),
            parameter_tabs,
        ),
        mainPanel(
            plotOutput("hist")
        )
    )
)

server <- function(input, output, session) {
    observeEvent(input$dist, {
        updateTabsetPanel(inputId = "params", selected = input$dist)
    })

    sample <- reactive({
        switch(input$dist,
               normal = rnorm(input$n, input$mean, input$sd),
               uniform = runif(input$n, input$min, input$max),
               exponential = rexp(input$n, input$rate)
        )
    })
    output$hist <- renderPlot(hist(sample()), res = 96)
}

shinyApp(ui, server)

```

::::
:::::

:::


Note that the value of (e.g.) `input$mean` is independent of whether or not its visible to the user. The underlying HTML control still exists; you just can’t see it.

### Wizard interface

You can also use this idea to create a “wizard”, a type of interface that makes it easier to collect a bunch of information by spreading it across multiple pages. Here we embed action buttons within each “page”, making it easy to go forward and back.

:::{.column-page-inset}

:::::{.my-r-code}
:::{.my-r-code-header}
:::::: {#cnj-ID-text}
: Numbered R Code Title
::::::
:::
::::{.my-r-code-container}
```{shinylive-r}
#| standalone: true
#| viewerHeight: 550
#| components: [editor, viewer]

## file: app.R
library(shiny)

ui <- fluidPage(
    tabsetPanel(
        id = "wizard",
        type = "hidden",
        tabPanel("page_1",
                 "Welcome!",
                 actionButton("page_12", "next")
        ),
        tabPanel("page_2",
                 "Only one page to go",
                 actionButton("page_21", "prev"),
                 actionButton("page_23", "next")
        ),
        tabPanel("page_3",
                 "You're done!",
                 actionButton("page_32", "prev")
        )
    )
)

server <- function(input, output, session) {
    switch_page <- function(i) {
        updateTabsetPanel(inputId = "wizard", selected = paste0("page_", i))
    }

    observeEvent(input$page_12, switch_page(2))
    observeEvent(input$page_21, switch_page(1))
    observeEvent(input$page_23, switch_page(3))
    observeEvent(input$page_32, switch_page(2))
}

shinyApp(ui, server)

```
::::
:::::

:::

Note the use of the `switch_page()` function to reduce the amount of duplication in the server code.

