filter_var <- function(x, val) {
    if (is.numeric(x)) {
        !is.na(x) & x >= val[1] & x <= val[2]
    } else if (is.factor(x)) {
        x %in% val
    } else {
        # No control, so don't filter
        TRUE
    }
}

ui <- fluidPage(
    sidebarLayout(
        sidebarPanel(
            purrr::map(names(iris), ~ make_ui(iris[[.x]], .x))
        ),
