server <- function(input, output, session) {
    selected <- reactive({
        each_var <- purrr::map(names(iris), ~ filter_var(iris[[.x]], input[[.x]]))
        purrr::reduce(each_var, ~ .x & .y)
    })

    output$data <- renderTable(head(iris[selected(), ], 12))
}

shinyApp(ui, server)

